<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; header('Content-Type: application/json; charset=utf-8'); $mid=(int)($_GET['medicine_id']??0); $qty=max(1,(int)($_GET['quantity']??1)); if(!$mid){echo json_encode(['ok'=>false]);exit;} $q=db()->prepare('SELECT m.retail_unit_price,m.min_profit_margin_pct,b.purchase_unit_cost FROM medicines m JOIN batches b ON b.medicine_id=m.id WHERE m.id=? AND b.units_remaining>=? AND (b.expiry_date IS NULL OR b.expiry_date>=CURDATE()) ORDER BY b.expiry_date IS NULL,b.expiry_date,b.id LIMIT 1');$q->execute([$mid,$qty]);$r=$q->fetch();if(!$r){echo json_encode(['ok'=>false,'message'=>'No valid batch']);exit;} $retail=(float)$r['retail_unit_price'];$cost=(float)$r['purchase_unit_cost'];$margin=(float)$r['min_profit_margin_pct'];$minimum=$cost*(1+$margin/100);$max=max(0,$retail-$minimum);echo json_encode(['ok'=>true,'retail'=>$retail,'cost'=>$cost,'margin_pct'=>$margin,'minimum_price'=>$minimum,'max_discount_per_unit'=>$max,'max_discount'=>$max*$qty]);